var runtimeAPI;
var apiUtils = require("../util");

async function getFlows(req, res) {
    var version = req.get("Node-RED-API-Version") || "v1";
    if (!/^v[12]$/.test(version)) {
        return res.status(400).json({ code: "invalid_api_version", message: "Invalid API Version requested" });
    }
    const { tenantConfigId } = await apiUtils.getUserDetails(req);
    if (!tenantConfigId || !req.query.appId || !req.user || !req.query.appType) {
        return apiUtils.rejectHandler(req, res, 'Missing required parameters');
    }
    var opts = {
        tenantConfigId,
        user: req.user,
        appId: req.query.appId,
        appType: req.query.appType,
        req: apiUtils.getRequestLogObject(req)
    }
    let flowsData;
    try {
        flowsData = await runtimeAPI.flows.getFlows(opts);
    } catch (error) {
        apiUtils.rejectHandler(req, res, error);
    }
    flowsData.flows = flowsData.flows.map(flow => {
        const { tenantConfigId, createdBy, appId, maskId, recStatus, ...rest } = flow;
        return rest;
    })
    if (version === "v1") {
        res.json(flowsData.flows);
    } else if (version === "v2") {
        res.json({
            success: true,
            flows: flowsData.flows,
            credentials: flowsData.credentials,
            rev: flowsData.rev
        });
    }
}
async function postFlows(req, res) {
    var version = req.get("Node-RED-API-Version") || "v1";
    if (!/^v[12]$/.test(version)) {
        return res.status(400).json({ code: "invalid_api_version", message: "Invalid API Version requested" });
    }

    const { username: emailId, tenantConfigId } = await apiUtils.getUserDetails(req);

    var opts = {
        emailId,
        tenantConfigId,
        user: req.user,
        deploymentType: "full",
        appId: req.query.appId,
        appType: req.query.appType,
        req: apiUtils.getRequestLogObject(req)
    }
    console.log('$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$')
    console.log(opts.appType)
    if (opts.deploymentType !== 'reload') {
        if (version === "v1") {
            opts.flows = { flows: req.body }
        } else {
            opts.flows = req.body.flows;
        }
    }

    let result;
    try {
        result = await runtimeAPI.flows.setFlows(opts);
    } catch (error) {
        apiUtils.rejectHandler(req, res, error);
    }
    if (version === "v1") {
        res.status(204).end();
    } else {
        res.json(result);
    }
}
module.exports = {
    init: function (_runtimeAPI) {
        runtimeAPI = _runtimeAPI;
    },
    get: getFlows,
    post: postFlows,
    getState: function (req, res) {
        const opts = {
            user: req.user,
            req: apiUtils.getRequestLogObject(req)
        }
        runtimeAPI.flows.getState(opts).then(function (result) {
            res.json(result);
        }).catch(function (err) {
            apiUtils.rejectHandler(req, res, err);
        })
    },
    postState: function (req, res) {
        const opts = {
            user: req.user,
            state: req.body.state || "",
            req: apiUtils.getRequestLogObject(req)
        }
        runtimeAPI.flows.setState(opts).then(function (result) {
            res.json(result);
        }).catch(function (err) {
            apiUtils.rejectHandler(req, res, err);
        })
    },
    getHttpNodes: async function (req, res) {
        const { tenantConfigId } = await apiUtils.getUserDetails(req);
        const appId = req.query.appId;
        try {
            let nodes = await runtimeAPI.storage.getHttpNodes(tenantConfigId, appId);
            nodes = nodes.map(node => {
                const { tenantConfigId, createdBy, appId, maskId, id, type, wires, x, y, recStatus, ...rest } = node;
                return rest;
            })
            return res.json({
                success: true,
                data: nodes
            });
        } catch (err) {
            return res.status(500).json({ success: false, message: err.message });
        }
    }
}
